     * @property option Selected option
     * @property isRange If option is given as a range. This field is meant to be read from the
     *   drone, ignore it when setting.
     */
    data class Setting(
        val settingId: String,
        val settingDescription: String,
        val option: Option,
        val isRange: Boolean,
    )

